$('#authForm').addEventListener('submit',e=>{e.preventDefault();let users=db.get('users',[]),email=$('#emailField').value.trim().toLowerCase(),pass=$('#passwordField').value;if(authMode==='register'){if(users.some(u=>u.email===email))return alert('E-mail já cadastrado.');let u={id:crypto.randomUUID(),name:$('#nameField').value.trim(),email,password:pass,phone:$('#phoneField').value.trim(),doc:$('#docField').value.trim(),role:'client'};users.push(u);db.set('users',users);db.set('session',u)}else{let u=users.find(u=>u.email.toLowerCase()===email&&u.password===pass);if(!u)return alert('E-mail ou senha inválidos.');db.set('session',u)}$('#authDialog').close();syncAuthUI()});
function openCart(){let lines=cartLines();if(!lines.length)return alert('Selecione ao menos um produto.');$('#cartItems').innerHTML=lines.map(x=>`<div class="cart-row"><div><b>${x.p.code}</b> ${x.p.name}<small>${money(x.p.price)} × ${x.qty}</small></div><strong>${money(x.p.price*x.qty)}</strong><button class="ghost" data-remove="${x.p.code}">×</button></div>`).join('');let sellers=db.get('sellers',[]);$('#sellerSelect').innerHTML=sellers.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');updateCartSummary();$('#cartDialog').showModal()}
function cartLines(){return Object.entries(cart).map(([code,qty])=>({p:products.find(x=>x.code===code),qty})).filter(x=>x.p)}
function totals(){let subtotal=cartLines().reduce((a,x)=>a+x.p.price*x.qty,0),promo=db.get('promo',{discount:0,freeShipping:false}),discount=subtotal*(Number(promo.discount)||0)/100,total=subtotal-discount;return{subtotal,discount,total,promo}}
function updateCartSummary(){let t=totals();$('#subtotalCart').textContent=money(t.subtotal);$('#discountCart').textContent='− '+money(t.discount);$('#shippingCart').textContent=t.promo.freeShipping?'GRÁTIS':'A combinar';$('#totalCart').textContent=money(t.total)}
$('#cartBtn').onclick=openCart;$('#closeCart').onclick=()=>$('#cartDialog').close();$('#cartItems').onclick=e=>{let code=e.target.dataset.remove;if(code){delete cart[code];db.set('cart',cart);$('#cartDialog').close();renderCatalog();if(Object.keys(cart).length)openCart()}};
$('#generateOrder').onclick=()=>{currentUser=db.get('session',null);if(!currentUser){$('#cartDialog').close();openAuth();return alert('Faça login ou crie seu cadastro antes de gerar o pedido.')}let sellers=db.get('sellers',[]),seller=sellers.find(s=>s.id===$('#sellerSelect').value)||sellers[0],lines=cartLines(),t=totals(),now=new Date(),order={id:'NT-'+now.getTime().toString().slice(-8),createdAt:now.toISOString(),customer:{name:currentUser.name,email:currentUser.email,phone:currentUser.phone||'',doc:currentUser.doc||''},seller,lines:lines.map(x=>({...x.p,qty:x.qty,lineTotal:x.p.price*x.qty})),subtotal:t.subtotal,discount:t.discount,total:t.total,freeShipping:t.promo.freeShipping,notes:$('#orderNotes').value};let orders=db.get('orders',[]);orders.unshift(order);db.set('orders',orders);makePdf(order);cart={};db.set('cart',cart);$('#cartDialog').close();renderCatalog();alert('Pedido gerado e salvo no histórico deste protótipo.');};
function makePdf(o){
  const rows=o.lines.map(l=>`<tr><td>${esc(l.code)}</td><td>${esc(l.name)}</td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(l.lineTotal)}</td></tr>`).join('');
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>${o.id}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#111827;font-size:12px}h1{font-size:22px;margin:0 0 8px}.meta{display:flex;justify-content:space-between;border-bottom:2px solid #111827;padding-bottom:10px;margin-bottom:14px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:16px 0}.box h3{font-size:11px;margin:0 0 6px}.box p{margin:3px 0}table{width:100%;border-collapse:collapse;margin-top:14px}th,td{padding:7px 5px;border-bottom:1px solid #d1d5db;text-align:left}th:nth-child(3),td:nth-child(3){text-align:center}th:nth-child(4),td:nth-child(4),th:nth-child(5),td:nth-child(5){text-align:right}.totals{margin-left:auto;width:280px;margin-top:16px}.totals div{display:flex;justify-content:space-between;padding:4px}.grand{font-size:16px;font-weight:bold;border-top:2px solid #111827;margin-top:4px}.footer{position:fixed;bottom:0;font-size:9px;color:#6b7280}.noprint{margin:15px 0;padding:10px;background:#eef6ff;border-radius:8px}@media print{.noprint{display:none}}</style></head><body><div class="noprint"><b>Pedido pronto.</b> Na janela de impressão escolha <b>Salvar como PDF</b>. Em celulares, use a opção de compartilhar/salvar PDF disponível no sistema.</div><h1>NIGHTECH — PEDIDO DE COMPRA</h1><div class="meta"><span><b>Pedido:</b> ${o.id}</span><span><b>Data:</b> ${new Date(o.createdAt).toLocaleString('pt-BR')}</span></div><div class="cols"><div class="box"><h3>COMPRADOR</h3><p>${esc(o.customer.name||'-')}</p><p>${esc(o.customer.email||'-')}</p><p>${esc(o.customer.phone||'')}</p><p>${esc(o.customer.doc||'')}</p></div><div class="box"><h3>VENDEDOR / CONSULTOR</h3><p>${esc(o.seller?.name||'-')}</p><p>${esc(o.seller?.email||'-')}</p><p>${esc(o.seller?.phone||'')}</p></div></div><table><thead><tr><th>Código</th><th>Produto</th><th>Qtd.</th><th>Unitário</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><div><span>Subtotal</span><b>${money(o.subtotal)}</b></div><div><span>Desconto</span><b>− ${money(o.discount)}</b></div><div><span>Frete</span><b>${o.freeShipping?'GRÁTIS':'A combinar'}</b></div><div class="grand"><span>Total</span><b>${money(o.total)}</b></div></div>${o.notes?`<h3>Observações</h3><p>${esc(o.notes)}</p>`:''}<div class="footer">Nightech • Rua Piramboia, 1082 - Jardim Stella, Santo André - SP • comercial@nightech.com.br</div><script>setTimeout(()=>window.print(),250)<\/script></body></html>`;
  const w=window.open('','_blank'); if(!w){alert('Permita pop-ups para gerar o PDF.');return} w.document.open();w.document.write(html);w.document.close();
}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
$('#historyBtn').onclick=()=>{let orders=db.get('orders',[]).filter(o=>currentUser?.role==='admin'||o.customer.email===currentUser?.email||o.seller?.email===currentUser?.email);$('#historyList').innerHTML=orders.length?orders.map(o=>`<div class="history-card"><b>${o.id}</b> • ${new Date(o.createdAt).toLocaleString('pt-BR')}<br><span>${o.lines.length} item(ns) • <b>${money(o.total)}</b></span></div>`).join(''):'<p class="muted">Nenhum pedido encontrado.</p>';$('#historyDialog').showModal()};$('#closeHistory').onclick=()=>$('#historyDialog').close();
